package com.example;

import org.eclipse.jdt.core.IClassFile;
import org.eclipse.jdt.core.IPackageFragment;
import org.eclipse.jdt.core.JavaModelException;

public class MyClass {
    public void processPackage(IPackageFragment pack) throws JavaModelException {
        // Using deprecated getClassFile
        IClassFile cf1 = pack.getClassFile("MyFile.class");
        System.out.println(cf1.getElementName());

        IClassFile cf2 = pack.getClassFile("AnotherFile.class");
        doSomethingWithClassFile(cf2);

        // Also works with a cast
        IClassFile cf3 = ((IPackageFragment) pack).getClassFile("YetAnother.class");
    }

    private void doSomethingWithClassFile(IClassFile cf) {
        // ...
    }
}

afterExample:
package com.example;

import org.eclipse.jdt.core.IClassFile;
import org.eclipse.jdt.core.IOrdinaryClassFile;
import org.eclipse.jdt.core.IPackageFragment;
import org.eclipse.jdt.core.JavaModelException;

public class MyClass {
    public void processPackage(IPackageFragment pack) throws JavaModelException {
        // Using modern getOrdinaryClassFile
        IClassFile cf1 = pack.getOrdinaryClassFile("MyFile.class"); // Type IClassFile still valid as IOrdinaryClassFile extends IClassFile
        System.out.println(cf1.getElementName());

        IClassFile cf2 = pack.getOrdinaryClassFile("AnotherFile.class");
        doSomethingWithClassFile(cf2);

        IClassFile cf3 = ((IPackageFragment) pack).getOrdinaryClassFile("YetAnother.class");
    }

    private void doSomethingWithClassFile(IClassFile cf) {
        // ...
    }
}

negativeExample:
package com.example;

import org.eclipse.jdt.core.IClassFile;
import org.eclipse.jdt.core.IOrdinaryClassFile;
import org.eclipse.jdt.core.IPackageFragment;
import org.eclipse.jdt.core.IType;
import org.eclipse.jdt.core.JavaModelException;

public class MyOtherClass {
    public void processClassFile(IClassFile classFile) throws JavaModelException {
        // This should not match, it's IClassFile.getType(), not IPackageFragment.getClassFile()
        IType type = classFile.getType();
        System.out.println(type.getElementName());
    }

    public void processOrdinaryPackage(IPackageFragment pack) throws JavaModelException {
        // This should not match, it's already using the correct method
        IOrdinaryClassFile ocf = pack.getOrdinaryClassFile("Existing.class");
        System.out.println(ocf.getElementName());
    }
}
